import React, { useState, useEffect } from 'react'
import { useParams, useNavigate } from 'react-router-dom'

function Coursedetails() {
  const { id } = useParams()
  const navigate = useNavigate()
  const [course, setCourse] = useState(null)
  const [enrolled, setEnrolled] = useState(false)

  useEffect(() => {
    fetch(`http://localhost:3001/courses/${id}`)
      .then(response => response.json())
      .then(data => setCourse(data))

    const saved = JSON.parse(localStorage.getItem('enrolledCourses')) || []
    const alreadyEnrolled = saved.find(c => c.id === parseInt(id))
    if (alreadyEnrolled) setEnrolled(true)
  }, [id])

  const handleEnroll = () => {
    const saved = JSON.parse(localStorage.getItem('enrolledCourses')) || []
    const alreadyEnrolled = saved.find(c => c.id === course.id)
    if (!alreadyEnrolled) {
      const updated = [...saved, course]
      localStorage.setItem('enrolledCourses', JSON.stringify(updated))
    }
    setEnrolled(true)
    navigate('/Mycourses')
  }

  if (!course) return <p className="text-center mt-4">Loading...</p>

  return (
    <div style={{ backgroundColor: '#81A6C6', minHeight: '100vh', padding: '40px 0' }}>
      <div className="container">
        <div className="card p-4 mx-auto" style={{ maxWidth: '700px', backgroundColor: '#F3E3D0', borderRadius: '12px', border: 'none' }}>
          <img
            src={course.image}
            alt={course.title}
            style={{ height: '200px', objectFit: 'contain' }}
            className="mb-3"
          />
          <h2 className="text-center" style={{ color: '#81A6C6', fontWeight: 'bold' }}>{course.title}</h2>
          <hr />
          <p><strong>Instructor:</strong> {course.instructor}</p>
          <p><strong>Duration:</strong> {course.duration}</p>
          <p><strong>Level:</strong> {course.level}</p>
          <p><strong>Price:</strong> {course.price}</p>
          <p><strong>Description:</strong> {course.description}</p>
          <div>
            <strong>Topics Covered:</strong>
            <ul className="mt-2">
              {course.topics && course.topics.map((topic, index) => (
                <li key={index}>{topic}</li>
              ))}
            </ul>
          </div>
          <button
            className="btn w-100 mt-3"
            onClick={handleEnroll}
            disabled={enrolled}
            style={{ backgroundColor: enrolled ? '#D2C4B4' : '#81A6C6', color: '#ffffff', borderRadius: '8px', fontWeight: 'bold' }}
          >
            {enrolled ? 'Already Enrolled' : 'Enroll Now'}
          </button>
          <button
            className="btn w-100 mt-2"
            onClick={() => navigate('/')}
            style={{ backgroundColor: '#D2C4B4', color: '#ffffff', borderRadius: '8px', fontWeight: 'bold' }}
          >
            ← Back to Courses
          </button>
        </div>
      </div>
    </div>
  )
}

export default Coursedetails
